<?php
declare(strict_types=1); require_once __DIR__ . '/../../helpers/auth.php'; require_once __DIR__ . '/../../models/Report.php'; require_role(['SUPER_ADMIN','CHURCH_ADMIN','STAFF']); $filters=['from'=>$_GET['from']??'','to'=>$_GET['to']??'','service_type_id'=>(int)($_GET['service_type_id']??0),'category_id'=>(int)($_GET['category_id']??0)];$dashboard=Report::dashboard();$services=Report::serviceSummary($filters);$events=Report::eventSummary($filters);$members=Report::memberSummary($filters);$pageTitle='Reports';$activeNav='reports';require __DIR__ . '/../../includes/header.php';?><div class="cmmp-page-header"><div><h1>Reports</h1><p>Operational summaries calculated from current CMMP data.</p></div></div><div class="cmmp-card mb-4"><form method="get" class="row g-3 align-items-end"><div class="col-md-3"><label>From</label><input class="form-control" type="date" name="from" value="<?=e($filters['from'])?>"></div><div class="col-md-3"><label>To</label><input class="form-control" type="date" name="to" value="<?=e($filters['to'])?>"></div><div class="col-md-3"><label>Service type</label><select class="form-select" name="service_type_id"><option value="0">All</option><?php foreach(Report::serviceTypes() as $type): ?><option value="<?= (int)$type['id']?>" <?= $filters['service_type_id']==$type['id']?'selected':''?>><?=e($type['name'])?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary">Apply filters</button></div></form></div><div class="row g-3 mb-4"><?php foreach(['total_members'=>'Total members','active_members'=>'Active members','upcoming_events'=>'Upcoming events','pending_services'=>'Pending services','upcoming_appointments'=>'Upcoming appointments','event_registrations'=>'Event registrations','attendance'=>'Present attendance'] as $key=>$label): ?><div class="col-sm-6 col-xl-3"><div class="cmmp-card"><div class="text-muted small"><?=e($label)?></div><div class="display-6 fw-semibold"><?= (int)$dashboard[$key]?></div></div></div><?php endforeach; ?></div><div class="row g-3"><div class="col-lg-7"><div class="cmmp-card"><h2 class="h5">Service request summary</h2><canvas id="serviceChart"></canvas><table class="table mt-3"><thead><tr><th>Service</th><th>Total</th><th>Completed</th><th>Pending</th></tr></thead><tbody><?php foreach($services as $row): ?><tr><td><?=e($row['name'])?></td><td><?= (int)$row['total']?></td><td><?= (int)$row['completed']?></td><td><?= (int)$row['pending']?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-lg-5"><div class="cmmp-card"><h2 class="h5">Event summary</h2><p>Total events: <strong><?= (int)$events['total_events']?></strong></p><p>Registrations: <strong><?= (int)$events['registrations']?></strong></p><p>Attendance: <strong><?= (int)$events['attendance']?></strong></p><p>Cancelled: <strong><?= (int)$events['cancelled']?></strong></p><h2 class="h5 mt-4">Membership status</h2><?php foreach($members as $row): ?><p class="mb-1"><?=e($row['membership_status'])?> <strong><?= (int)$row['total']?></strong></p><?php endforeach; ?></div></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4"></script><script>new Chart(document.getElementById('serviceChart'),{type:'bar',data:{labels:<?=json_encode(array_column($services,'name'))?>,datasets:[{label:'Requests',data:<?=json_encode(array_map('intval',array_column($services,'total')))?>,backgroundColor:'#1f5b5e'}]},options:{responsive:true,plugins:{legend:{display:false}}}});</script><?php require __DIR__ . '/../../includes/footer.php'; ?>
